@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")" @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services

<div class="settings-section profile-section">
    <h2>Profile Settings</h2>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="avatar-preview">
        <img src="@avatarUrl" alt="Avatar" />
        <p class="avatar-url">@avatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="displayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="email" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="bio" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && displayName == "" && email == "")
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        displayName = Profile.DisplayName;
        email = Profile.Email;
        bio = Profile.Bio;
        avatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        LoadFromProfile();
        successMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services

<div class="settings-section notifications-section">
    <h2>Notification Preferences</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="emailNotifications" />
            <span>Email Notifications</span>
        </label>
        <label class="toggle-item">
            <input type="checkbox" @bind="pushNotifications" />
            <span>Push Notifications</span>
        </label>
        <label class="toggle-item">
            <input type="checkbox" @bind="weeklyDigest" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in allChannels)
        {
            <label class="channel-item">
                <input type="checkbox" checked="@IsChannelMuted(channel)" @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();

    private static readonly string[] allChannels = { "general", "marketing", "engineering", "design", "announcements" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new List<string>(Prefs.MutedChannels);
        }
    }

    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, new List<string>(mutedChannels));
        await OnSave.InvokeAsync(updated);
    }
}

@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services

<div class="settings-section security-section">
    <h2>Security Settings</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
        </button>
        @if (passwordPanelOpen)
        {
            <div class="panel-content">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="confirmPassword" />
                </div>
                @if (passwordError is not null)
                {
                    <div class="error-message">@passwordError</div>
                }
                @if (passwordSuccess is not null)
                {
                    <div class="toast success">@passwordSuccess</div>
                }
                <button class="btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="status-row">
            <span class="status-indicator @(Settings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                @(Settings?.TwoFactorEnabled == true ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="last-change">Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Settings?.Sessions is not null)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != currentSessionId)
                                {
                                    <button class="btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="dialog-overlay">
            <div class="dialog">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in @sessionToRevoke.Location?</p>
                <div class="dialog-actions">
                    <button class="btn-danger" @onclick="RevokeConfirmedAsync">Revoke</button>
                    <button class="btn-secondary" @onclick="() => sessionToRevoke = null">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private string? passwordSuccess;
    private ActiveSession? sessionToRevoke;
    private string currentSessionId = "sess-1";

    private async Task UpdatePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New passwords do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = "Password updated successfully!";
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session) => sessionToRevoke = session;

    private async Task RevokeConfirmedAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services

<div class="settings-section appearance-section">
    <h2>Appearance Settings</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme" checked="@(selectedTheme == theme)" @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size" checked="@(selectedFontSize == size)" @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="selectedLanguage">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="compactMode" />
            <span>Compact Mode</span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{selectedTheme.ToLower()} font-{selectedFontSize.ToLower()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
    }
}

