@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && displayName == "" && email == "")
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        displayName = Profile.DisplayName;
        email = Profile.Email;
        bio = Profile.Bio;
        avatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);
        successMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        LoadFromProfile();
        successMessage = null;
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}
