@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services

<div class="settings-section appearance-section">
    <h2>Appearance Settings</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme" checked="@(selectedTheme == theme)" @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size" checked="@(selectedFontSize == size)" @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="selectedLanguage">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="compactMode" />
            <span>Compact Mode</span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{selectedTheme.ToLower()} font-{selectedFontSize.ToLower()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
    }
}

arguments.file_text:
@page "/settings"
@namespace sv_5ee6c925c492480aab31ea433c56b930.Components.Pages.Settings
@using sv_5ee6c925c492480aab31ea433c56b930.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="SetSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@notifications" OnSave="SaveNotificationsAsync" />
                break;
            case "Security":
                <SecuritySection Settings="@security" OnChangePassword="ChangePasswordAsync" OnRevokeSession="RevokeSessionAsync" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@appearance" OnSave="SaveAppearanceAsync" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private UserProfile? profile;
    private NotificationPrefs? notifications;
    private SecuritySettings? security;
    private AppearanceSettings? appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private void SetSection(string section)
    {
        activeSection = section;
        _ = LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        switch (activeSection)
        {
            case "Profile":
                profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                notifications = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                appearance = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notifications = updated;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
    }
}

/* Settings Page Layout */
.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 200px;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.2s, color 0.2s;
    font-weight: 500;
    color: #555;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar li.active {
    background-color: #4f46e5;
    color: #fff;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section {
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    padding: 2rem;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #111;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #333;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-group select {
    appearance: auto;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    background-color: #4f46e5;
    color: #fff;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background-color: #4338ca;
}

.btn-secondary {
    background-color: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background-color: #e5e7eb;
}

.btn-danger {
    background-color: #dc2626;
    color: #fff;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.85rem;
}

.btn-danger:hover {
    background-color: #b91c1c;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast / Success Message */
.toast.success {
    background-color: #ecfdf5;
    border: 1px solid #6ee7b7;
    color: #065f46;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-weight: 500;
}

.error-message {
    color: #dc2626;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-preview img {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e5e7eb;
}

.avatar-url {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6b7280;
    word-break: break-all;
}

/* Toggle Items */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    cursor: pointer;
    font-weight: 400;
}

.toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #4f46e5;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding-left: 0.25rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    accent-color: #4f46e5;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #f3f4f6;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #e5e7eb;
}

/* Two-Factor Section */
.twofa-section {
    margin-bottom: 1.5rem;
}

.status-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.status-indicator {
    padding: 0.35rem 0.75rem;
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 600;
}

.status-indicator.enabled {
    background-color: #ecfdf5;
    color: #065f46;
}

.status-indicator.disabled {
    background-color: #fef2f2;
    color: #991b1b;
}

.last-change {
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.65rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e5e7eb;
}

.sessions-table th {
    background: #f9fafb;
    font-weight: 600;
    color: #374151;
}

.current-badge {
    background: #dbeafe;
    color: #1e40af;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
